   116  static bool
   117  parse_ascii_port(char *port, unsigned short *out)
   118  {
   119      unsigned long parsed;
   120      char *end_ptr;
   121
   122      errno = 0;
   123      parsed = strtoul(port, &end_ptr, 10);
   124
   125      if (UNLIKELY(errno != 0))
   126          return false;
   127
   128      if (UNLIKELY(*end_ptr != '\0'))
   129          return false;
   130
   131      if (UNLIKELY((unsigned long)(unsigned short)parsed != parsed))
   132          return false;
   133
   134      *out = htons((unsigned short)parsed);
   135      return true;
   136  }
