    37  static void fourty_two_and_free(void *str)
    38  {
    39      if (LIKELY(str)) {
    40          char *s = str;
    41          while (*s)
    42              *s++ = 42;
    43          __asm__ __volatile__("" :: "g"(s) : "memory");
    44          free(str);
    45      }
    46  }
