    48  static struct cache_entry *create_realm_file(
    49            const char *key,
    50            void *context __attribute__((unused)))
    51  {
    52      struct realm_password_file_t *rpf = malloc(sizeof(*rpf));
    53      struct config *f;
    54      struct config_line l;
    55
    56      if (UNLIKELY(!rpf))
    57          return NULL;
    58
    59      rpf->entries = hash_str_new(fourty_two_and_free, fourty_two_and_free);
    60      if (UNLIKELY(!rpf->entries))
    61          goto error_no_close;
    62
    63      f = config_open(key);
    64      if (!f)
    65          goto error_no_close;
    66
    67      while (config_read_line(f, &l)) {
    68          /* FIXME: Storing plain-text passwords in memory isn't a good idea. */
    69          switch (l.type) {
    70          case CONFIG_LINE_TYPE_LINE: {
    71              char *username = strdup(l.key);
    72              if (!username)
    73                  goto error;
    74
    75              char *password = strdup(l.value);
    76              if (!password) {
    77                  free(username);
    78                  goto error;
    79              }
    80
    81              int err = hash_add_unique(rpf->entries, username, password);
    82              if (LIKELY(!err))
    83                  continue;
    84
    85              free(username);
    86              free(password);
    87
    88              if (err == -EEXIST) {
    89                  lwan_status_warning(
    90                      "Username entry already exists, ignoring: \"%s\"",
    91                      l.key);
    92                  continue;
    93              }
    94
    95              goto error;
    96          }
    97          default:
    98              config_error(f, "Expected username = password");
    99              break;
   100          }
   101      }
   102
   103      if (config_last_error(f)) {
   104          lwan_status_error("Error on password file \"%s\", line %d: %s",
   105                key, config_cur_line(f), config_last_error(f));
   106          goto error;
   107      }
   108
   109      config_close(f);
   110      return (struct cache_entry *)rpf;
   111
   112  error:
   113      config_close(f);
   114  error_no_close:
   115      hash_free(rpf->entries);
   116      free(rpf);
   117      return NULL;
   118  }
