    84  static enum lwan_http_status parse_http_code(const char *code,
    85                                               enum lwan_http_status fallback)
    86  {
    87      const char *known;
    88      int as_int;
    89
    90      if (!code)
    91          return fallback;
    92
    93      as_int = parse_int(code, 999);
    94      if (as_int == 999)
    95          return fallback;
    96
    97      known = lwan_http_status_as_string_with_code((enum lwan_http_status)as_int);
    98      if (!strncmp(known, "999", 3))
    99          return fallback;
   100
   101      return (enum lwan_http_status)as_int;
   102  }
